// Normalising entry node. Everything downstream reads THIS, never the trigger,
// so the skill stays testable and survives new entry paths.
const items = $input.all();
const src = items.length ? (items[0].json || {}) : {};
const OWNER_CHAT = 0;

// The Schedule Trigger emits a timestamp payload with no chat_id / action.
const isScheduled = !src.action && !src.chat_id;
if (isScheduled) {
  return [{ json: { action: 'scheduled', chat_id: OWNER_CHAT, language: 'en', source: 'schedule', text: '' } }];
}
return [{ json: {
  action: (src.action === 'reply' ? 'invoke' : (src.action || 'invoke')),
  chat_id: src.chat_id || OWNER_CHAT,
  language: src.language || 'en',
  text: String(src.text || src.reply_text || ''),
  cb_action: src.cb_action || '',
  ref: src.ref || '',
  source: 'orchestrator'
} }];

// Turn the parsed request into a concrete search plan.
// All date maths is done here in plain JS, never by the model.
const ctx = $('Prep Input').first().json;
const raw = $input.first().json;
const c = raw.message && raw.message.content ? raw.message.content : raw;
let p = {};
try { p = typeof c === 'string' ? JSON.parse(c) : (c || {}); } catch (e) { p = {}; }

let intent = ['create','list','cancel','status'].includes(p.intent) ? p.intent : 'unclear';
// Naming a route is a mechanical signal, so do not leave it to the model:
// "cheapest flight from Berlin to Milan" is a new watch, not a status question.
if (intent === 'status' && String(p.destination_iata || '').trim()) intent = 'create';

// Window: 8 weeks (about two months) unless he names one. His explicit call.
const CFG = (() => { try { return $('⚙️ Config').first().json; } catch (e) { return {}; } })();
const weeks = Math.min(Math.max(Number(p.window_weeks) || Number(CFG.default_window_weeks) || 8, 1), 12);

// Patterns: whatever he actually said, honoured exactly. Only fall back when silent.
const ALL = ['FRI_SUN','SAT_SUN','THU_SUN','SAT_MON','THU_SAT'];
let pats = Array.isArray(p.patterns) ? p.patterns.filter(x => ALL.includes(x)) : [];
const patsGiven = pats.length > 0;
if (!patsGiven) pats = ['FRI_SUN'];   // his default: a plain Fri to Sun weekend

const cadence = p.cadence === 'daily' ? 'daily' : 'weekly';

let budget = Number(p.budget_eur);
if (!isFinite(budget) || budget <= 0) budget = 0;
const budgetFloored = budget > 0 && budget < 50;
if (budgetFloored) budget = 50;

// Home airport. Berlin unless he says otherwise, and the card always states it
// so a wrong assumption is visible rather than silent.
const destIata = String(p.destination_iata || '').toUpperCase().slice(0,3);
let originIata = String(p.origin_iata || '').toUpperCase().slice(0,3);
const originAssumed = !originIata && !!destIata;
if (originAssumed) originIata = String(CFG.home_airport || 'BER').toUpperCase();

// A create with no destination cannot be saved. Ask instead of storing a dead alert.
const needsAsk = intent === 'create' && !destIata;

const pad = (n) => (n < 10 ? '0' : '') + n;
const iso = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth()+1) + '-' + pad(d.getUTCDate());
const add = (d, n) => { const x = new Date(d.getTime()); x.setUTCDate(x.getUTCDate() + n); return x; };
const today = new Date(); today.setUTCHours(12,0,0,0);
const dow = today.getUTCDay();
const anchor = add(today, ((8 - (dow === 0 ? 7 : dow)) % 7) || 7);

// A city is not an airport. "Rome" means Fiumicino AND Ciampino, and Google
// Flights accepts a comma list in ONE search, so covering both costs nothing.
const CITY_AIRPORTS = {
  FCO:'FCO,CIA', LHR:'LHR,LGW,STN,LTN', CDG:'CDG,ORY,BVA', MXP:'MXP,LIN,BGY',
  JFK:'JFK,EWR,LGA', IST:'IST,SAW', WAW:'WAW,WMI', ARN:'ARN,NYO', BRU:'BRU,CRL',
  VCE:'VCE,TSF', OSL:'OSL,TRF', BCN:'BCN,GRO', MAD:'MAD', LIS:'LIS', ATH:'ATH',
  VIE:'VIE', AMS:'AMS', NAP:'NAP', DUB:'DUB', CPH:'CPH', ZRH:'ZRH', MUC:'MUC',
  BER:'BER', OPO:'OPO', PMO:'PMO', NCE:'NCE', TXL:'BER', SXF:'BER'
};
const airportsFor = (iata) => CITY_AIRPORTS[iata] || iata;
// Display names, so a header never reads "Berlin to LIS" when the model
// returns the code but skips the city name.
const CITY_NAMES = {
  FCO:'Rome', CIA:'Rome', LHR:'London', CDG:'Paris', MXP:'Milan', JFK:'New York',
  IST:'Istanbul', WAW:'Warsaw', ARN:'Stockholm', BRU:'Brussels', VCE:'Venice',
  OSL:'Oslo', BCN:'Barcelona', MAD:'Madrid', LIS:'Lisbon', ATH:'Athens',
  VIE:'Vienna', AMS:'Amsterdam', NAP:'Naples', DUB:'Dublin', CPH:'Copenhagen',
  ZRH:'Zurich', MUC:'Munich', BER:'Berlin', OPO:'Porto', PMO:'Palermo', NCE:'Nice'
};
const cityName = (given, iata) => {
  const g = String(given || '').trim();
  // a bare 3-letter code is not a name
  if (g && !/^[A-Z]{3}$/.test(g)) return g;
  return CITY_NAMES[iata] || iata;
};

const OFFSETS = { THU_SUN:[3,6], FRI_SUN:[4,6], SAT_SUN:[5,6], SAT_MON:[5,7], THU_SAT:[3,5] };

const pairs = [];
for (let w = 0; w < weeks; w++) {
  const mon = add(anchor, w * 7);
  for (const pat of pats) {
    const o = OFFSETS[pat];
    pairs.push({ pattern: pat, out: iso(add(mon, o[0])), ret: iso(add(mon, o[1])) });
  }
}
const runsPerMonth = cadence === 'daily' ? 30 : 4;

return [{ json: {
  ...ctx,
  intent: needsAsk ? 'ask' : intent,
  ask_reason: needsAsk ? 'destination' : '',
  origin: originIata ? airportsFor(originIata) : '',
  destination: destIata ? airportsFor(destIata) : '',
  origin_iata: originIata, destination_iata: destIata,
  origin_name: cityName(p.origin_name, originIata) || (originAssumed ? 'Berlin' : originIata),
  dest_name: cityName(p.destination_name, destIata),
  origin_assumed: originAssumed,
  origin_from_country: !!p.origin_from_country,
  dest_from_country: !!p.destination_from_country,
  budget_eur: budget, budget_floored: budgetFloored,
  window_weeks: weeks, window_given: !!Number(p.window_weeks),
  patterns: pats, patterns_given: patsGiven,
  cadence, pairs,
  searches_per_run: pairs.length,
  searches_per_month: pairs.length * runsPerMonth,
  cancel_hint: String(p.cancel_hint || ''),
  language: p.language || ctx.language || 'en',
  probe_url: (originIata && destIata && pairs.length)
    ? ('https://serpapi.com/search.json?engine=google_flights&departure_id=' + airportsFor(originIata) +
       '&arrival_id=' + airportsFor(destIata) + '&outbound_date=' + pairs[0].out + '&return_date=' + pairs[0].ret +
       '&currency=EUR&hl=en&gl=de&type=1')
    : ''
}}];

// Compare the stated budget against what the route actually costs right now.
// price_insights is free inside the search we already paid for.
const ctx = $('Normalise Request').first().json;
const r = $input.first().json || {};
const pi = r.price_insights || null;
const all = (r.best_flights || []).concat(r.other_flights || []);
const prices = all.map(x => x.price).filter(x => typeof x === 'number').sort((a,b) => a-b);

const lowest = pi && typeof pi.lowest_price === 'number' ? pi.lowest_price : (prices[0] || null);
const range = pi && Array.isArray(pi.typical_price_range) ? pi.typical_price_range : null;
const searchFailed = !!r.error || (!prices.length && !lowest);

let verdict = 'ok', note = '';
if (!searchFailed && ctx.budget_eur > 0 && range && range.length === 2) {
  if (ctx.budget_eur < range[0] * 0.6) { verdict = 'unrealistic'; note = 'well below the typical range'; }
  else if (ctx.budget_eur < range[0])  { verdict = 'tight'; note = 'below the typical range but not impossible'; }
} else if (!searchFailed && ctx.budget_eur > 0 && lowest && ctx.budget_eur < lowest * 0.6) {
  verdict = 'unrealistic'; note = 'well under the cheapest fare on the market today';
}

// Readable id: ROME-0908-K3 rather than FW-20260908-66wz.
const slug = String(ctx.dest_name || ctx.destination || 'TRIP')
  .toUpperCase().replace(/[^A-Z]/g, '').slice(0, 8) || 'TRIP';
const n = new Date();
const pad = (x) => (x < 10 ? '0' : '') + x;
const stamp = pad(n.getMonth() + 1) + pad(n.getDate());
const rnd = Math.random().toString(36).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 2) || 'X1';

return [{ json: { ...ctx,
  market_lowest: lowest, market_range: range,
  market_level: pi ? (pi.price_level || '') : '',
  search_failed: searchFailed, verdict, verdict_note: note,
  alert_id: slug + '-' + stamp + '-' + rnd }}];

const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const capHtml = (s, max) => {
  let t = String(s || '');
  if (t.length <= max) return t;
  t = t.slice(0, max);
  const lt = t.lastIndexOf('<'), gt = t.lastIndexOf('>');
  if (lt > gt) t = t.slice(0, lt);
  const open = []; const re = /<(\/?)([a-zA-Z]+)[^>]*>/g; let m;
  while ((m = re.exec(t)) !== null) {
    if (m[1] === '/') { const i = open.lastIndexOf(m[2]); if (i !== -1) open.splice(i, 1); }
    else open.push(m[2]);
  }
  while (open.length) t += '</' + open.pop() + '>';
  return t + '\n…(truncated)';
};

const d = $input.first().json;
const de = d.language === 'de';
const eur = (n) => (n == null ? '?' : '€' + Math.round(n));
const PAT = { FRI_SUN:'Fri to Sun', THU_SUN:'Thu to Sun', SAT_SUN:'Sat to Sun', SAT_MON:'Sat to Mon', THU_SAT:'Thu to Sat' };
const L = [];

L.push('<b>' + esc(de ? '🛫 Flug-Alarm aktiv' : '🛫 Flight alert active') + '</b>');
L.push('');
L.push('<b>' + esc(d.origin_name + ' to ' + d.dest_name) + '</b> (' + esc(d.origin + ' to ' + d.destination) + ')');
if (d.dest_from_country || d.origin_from_country) {
  const parts = [];
  if (d.origin_from_country) parts.push(d.origin_name);
  if (d.dest_from_country) parts.push(d.dest_name);
  L.push('<i>' + esc((de ? 'Land genannt, ich nehme die Hauptstadt: ' : 'You named a country, so I am using the capital: ')
        + parts.join(', ')) + '</i>');
}
if (d.origin_assumed) {
  L.push('<i>' + esc(de ? 'Abflug Berlin angenommen. Sag es, wenn du woanders startest.'
                        : 'Assumed you fly from Berlin. Tell me if not.') + '</i>');
}
if (d.budget_eur > 0) L.push((de ? 'Budget: ' : 'Budget: ') + '<b>' + eur(d.budget_eur) + '</b>');
else L.push('<i>' + esc(de ? 'Kein Budget gesetzt, ich zeige dir einfach die Preise.'
                           : 'No budget set, I will just show you the prices.') + '</i>');
L.push((de ? 'Zeitraum: ' : 'Window: ') + d.window_weeks + (de ? ' Wochen' : ' weeks')
       + (d.window_given ? '' : esc(de ? ' (Standard)' : ' (default)')));
L.push((de ? 'Wochenenden: ' : 'Weekends: ') + esc(d.patterns.map(p => PAT[p] || p).join(', '))
       + (d.patterns_given ? '' : esc(de ? ' (Standard)' : ' (default)')));
L.push((de ? 'Prüfung: ' : 'Checks: ') + (d.cadence === 'daily'
       ? (de ? 'täglich 08:00' : 'daily 08:00')
       : (de ? 'dienstags 08:00' : 'Tuesday 08:00')));

if (d.budget_floored) L.push('', esc(de ? '⚠️ Budget auf das Minimum von €50 angehoben.' : '⚠️ Budget raised to the €50 minimum.'));

L.push('');
if (d.search_failed) {
  L.push(esc(de ? 'Marktpreise hole ich beim ersten Lauf, der Alarm läuft.'
                : 'I will pull market rates on the first run, the alert is live.'));
} else {
  L.push('<b>' + esc(de ? 'Markt heute' : 'Market today') + '</b>');
  if (d.market_lowest != null) L.push((de ? 'Günstigster Preis: ' : 'Cheapest right now: ') + '<b>' + eur(d.market_lowest) + '</b>');
  if (d.market_range) L.push((de ? 'Üblich: ' : 'Typical: ') + eur(d.market_range[0]) + ' to ' + eur(d.market_range[1]));
  if (d.verdict === 'unrealistic') L.push('', esc((de ? '⚠️ Dein Budget liegt ' : '⚠️ Your budget is ') + d.verdict_note + '.'));
  else if (d.verdict === 'tight') L.push('', esc((de ? 'Knapp, aber machbar. ' : 'Tight but plausible. ')));
}

L.push('');
L.push('<i>' + esc(d.searches_per_run + (de ? ' Suchen pro Lauf, ca. ' : ' searches per run, about ')
      + d.searches_per_month + (de ? ' pro Monat.' : ' per month.')) + '</i>');
if (d.searches_per_month > 250) L.push('<i>' + esc(de ? '⚠️ Über dem kostenlosen Kontingent (250/Monat).' : '⚠️ Above the free quota (250/month).') + '</i>');
L.push('<code>' + esc(d.alert_id) + '</code>');

return [{ json: { ...d, message: capHtml(L.join('\n'), 3800) } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const capHtml = (s, max) => {
  let t = String(s || '');
  if (t.length <= max) return t;
  t = t.slice(0, max);
  const lt = t.lastIndexOf('<'), gt = t.lastIndexOf('>');
  if (lt > gt) t = t.slice(0, lt);
  const open = [];
  const re = /<(\/?)([a-zA-Z]+)[^>]*>/g;
  let m;
  while ((m = re.exec(t)) !== null) {
    if (m[1] === '/') { const i = open.lastIndexOf(m[2]); if (i !== -1) open.splice(i, 1); }
    else open.push(m[2]);
  }
  while (open.length) t += '</' + open.pop() + '>';
  return t + '\n…(truncated)';
};

const ctx = $('Prep Input').first().json;
const de = ctx.language === 'de';
const rows = $input.all().map(i => i.json).filter(r => r && r.alert_id);
const active = rows.filter(r => String(r.status || '').toLowerCase() === 'active');
const L = [];
L.push('<b>' + esc(de ? '🛫 Deine Flug-Alarme' : '🛫 Your flight alerts') + '</b>');
L.push('');
if (!active.length) {
  L.push(esc(de ? 'Keine aktiven Alarme. Sag mir einfach: "beobachte Berlin nach Warschau unter 120 Euro".'
                : 'No active alerts. Just tell me: "watch Berlin to Warsaw under 120 euro".'));
} else {
  let i = 1;
  for (const r of active) {
    L.push('<b>' + i + '. ' + esc((r.origin_name || r.origin) + ' → ' + (r.dest_name || r.destination)) + '</b>  €' + esc(r.budget_eur));
    const bits = [esc(String(r.window_weeks || '') + (de ? ' Wochen' : ' weeks')), esc(String(r.cadence || ''))];
    if (r.last_best_price) bits.push((de ? 'zuletzt ab €' : 'last seen from €') + esc(r.last_best_price));
    L.push('   ' + bits.join(' · '));
    L.push('   <code>' + esc(r.alert_id) + '</code>');
    i++;
  }
}
return [{ json: { ...ctx, message: capHtml(L.join('\n'), 3800) } }];

// Never guess which alert to cancel. A wrong cancellation is silent data loss.
const ctx = $('Normalise Request').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.alert_id);
const active = rows.filter(r => String(r.status || '').toLowerCase() === 'active');
const hint = String(ctx.cancel_hint || ctx.text || '').toLowerCase().trim();
const norm = (s) => String(s || '').toLowerCase();
const label = (r) => (r.origin_name || r.origin) + ' to ' + (r.dest_name || r.destination);

// 1. An exact alert id anywhere in the message wins outright.
const exact = active.find(r => r.alert_id && hint.includes(norm(r.alert_id)));
if (exact) return [{ json: { ...ctx, matched: true, alert_id: exact.alert_id, route: label(exact) } }];

// 2. If it LOOKS like an id but matched nothing, refuse rather than fall back.
if (/[a-z]{2,10}-\d{3,4}-[a-z0-9]{2,}/i.test(hint)) {
  return [{ json: { ...ctx, matched: false, reason: 'none',
    candidates: active.map(r => ({ alert_id: r.alert_id, route: label(r) })) } }];
}

// 3. Match on city or airport code.
let hits = active.filter(r => {
  const hay = [r.origin, r.destination, r.origin_name, r.dest_name]
    .flatMap(x => String(x || '').split(',')).map(norm).filter(Boolean);
  return hay.some(h => h.length > 2 && hint.includes(h));
});

// 4. Only collapse to the single active alert on a genuinely vague instruction.
if (!hits.length && active.length === 1 && /^(cancel|stop|delete|remove|loesche|lösche|beende)\b/.test(hint)) {
  hits = active.slice();
}

if (hits.length !== 1) {
  return [{ json: { ...ctx, matched: false,
    reason: hits.length > 1 ? 'ambiguous' : 'none',
    candidates: active.map(r => ({ alert_id: r.alert_id, route: label(r) })) } }];
}
return [{ json: { ...ctx, matched: true, alert_id: hits[0].alert_id, route: label(hits[0]) } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const capHtml = (s, max) => {
  let t = String(s || '');
  if (t.length <= max) return t;
  t = t.slice(0, max);
  const lt = t.lastIndexOf('<'), gt = t.lastIndexOf('>');
  if (lt > gt) t = t.slice(0, lt);
  const open = [];
  const re = /<(\/?)([a-zA-Z]+)[^>]*>/g;
  let m;
  while ((m = re.exec(t)) !== null) {
    if (m[1] === '/') { const i = open.lastIndexOf(m[2]); if (i !== -1) open.splice(i, 1); }
    else open.push(m[2]);
  }
  while (open.length) t += '</' + open.pop() + '>';
  return t + '\n…(truncated)';
};

const d = $input.first().json;
const de = d.language === 'de';
let t;
if (d.matched) {
  t = '<b>' + esc(de ? '🗑 Alarm gelöscht' : '🗑 Alert cancelled') + '</b>\n' + esc(d.route) + '\n<code>' + esc(d.alert_id) + '</code>';
} else if (d.reason === 'ambiguous') {
  const lines = (d.candidates || []).map((c, i) => (i+1) + '. ' + esc(c.route) + '  <code>' + esc(c.alert_id) + '</code>');
  t = esc(de ? 'Ich konnte nicht sicher sagen, welchen du meinst. Nenn mir die ID:' : 'I could not tell for sure which one you meant. Give me the ID:') + '\n\n' + lines.join('\n');
} else {
  t = esc(de ? 'Dazu habe ich keinen aktiven Alarm gefunden.' : 'I could not find an active alert for that.');
}
return [{ json: { ...d, message: capHtml(t, 3800) } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const d = $('Normalise Request').first().json;
const raw = String(($('Prep Input').first().json || {}).text || '').trim();
const de = d.language === 'de';

// /start and /help are a first hello, not a failure. Same card, different opener,
// so someone who has never seen this bot gets the format instead of a shrug.
const isHello = /^\/(start|help)\b/i.test(raw);

const L = [];
if (isHello) {
  L.push('<b>' + esc(de ? '✈️ Flug-Wächter' : '✈️ Flight Watcher') + '</b>');
  L.push(esc(de
    ? 'Ich beobachte Flugpreise für ein Wochenende und melde mich dienstags früh mit dem Stand.'
    : 'I watch flight prices for a weekend trip and message you Tuesday mornings with where they stand.'));
} else {
  L.push('<b>' + esc(de ? '✈️ Ich mache nur Flüge' : '✈️ I only do flights') + '</b>');
  L.push(esc(de
    ? 'Das habe ich nicht verstanden. Ich kann nur Flugpreise beobachten, sonst nichts.'
    : 'I did not understand that. Watching flight prices is the only thing I do.'));
}

L.push('');
L.push('<b>' + esc(de ? 'So fragst du' : 'How to ask') + '</b>');
L.push(esc(de ? 'Nenn Ziel und Budget, der Rest ist optional:' : 'Name a destination and a budget, the rest is optional:'));
L.push('');
L.push('<code>' + esc(de ? 'beobachte Flüge nach Rom unter 150 Euro' : 'watch flights to Rome under 150 euro') + '</code>');
L.push('<code>' + esc(de ? 'Flüge von München nach Lissabon unter 200, Donnerstag bis Sonntag' : 'flights from Munich to Lisbon under 200, Thursday to Sunday') + '</code>');
L.push('');
L.push('<b>' + esc(de ? 'Weitere Befehle' : 'Other things I understand') + '</b>');
L.push('<code>' + esc(de ? 'zeig mir meine Flug-Alarme' : 'show my flight alerts') + '</code>');
L.push('<code>' + esc(de ? 'wie sehen die Preise gerade aus' : 'how are my alerts looking') + '</code>');
L.push('<code>' + esc(de ? 'lösche den Rom-Alarm' : 'cancel the Rome alert') + '</code>');
L.push('');
L.push('<i>' + esc(de
  ? 'Standard: Freitag bis Sonntag, 8 Wochen im Voraus, Abflug Berlin. Sag es einfach dazu, wenn du etwas anderes willst. Sprachnachrichten gehen auch.'
  : 'Defaults: Friday to Sunday, 8 weeks ahead, departing Berlin. Just say so if you want something else. Voice notes work too.') + '</i>');
L.push('');
L.push('<i>' + esc(de
  ? 'Kalender, E-Mail oder sonst irgendwas kann ich nicht. Nur Flüge.'
  : 'I cannot do calendars, email or anything else. Only flights.') + '</i>');

return [{ json: { ...d, message: L.join('\n') } }];

// Build the search plan. Cost is exactly patterns x weekends x routes, because
// Google Flights has no date-grid endpoint: one search per date pair, always.
const CFG = (() => { try { return $('⚙️ Config').first().json; } catch (e) { return {}; } })();
const MAX_SEARCHES_PER_RUN = Number(CFG.max_searches_per_run) || 60;
const rows = $input.all().map(i => i.json).filter(r => r && r.alert_id);
const active = rows.filter(r => String(r.status || '').toLowerCase() === 'active');

const pad = (n) => (n < 10 ? '0' : '') + n;
const iso = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth()+1) + '-' + pad(d.getUTCDate());
const add = (d, n) => { const x = new Date(d.getTime()); x.setUTCDate(x.getUTCDate() + n); return x; };
const today = new Date(); today.setUTCHours(12,0,0,0);
const dow = today.getUTCDay();                       // 0 = Sunday, 2 = Tuesday
const anchor = add(today, ((8 - (dow === 0 ? 7 : dow)) % 7) || 7);   // next Monday
const OFFSETS = { THU_SUN:[3,6], FRI_SUN:[4,6], SAT_SUN:[5,6], SAT_MON:[5,7], THU_SAT:[3,5] };
const isTuesday = dow === 2;

const out = [];
for (const r of active) {
  const cadence = String(r.cadence || 'weekly').toLowerCase();
  const fullRun = cadence !== 'weekly' || isTuesday;

  const weeks = Math.min(Math.max(Number(r.window_weeks) || 6, 1), 12);
