  if (!o || !d || !pats.length) continue;


  // ---- LIGHT DAILY CHECK ----
  // A weekly alert does its full sweep on Tuesday. On the other six days it
  // re-prices ONLY the weekend that was cheapest, so a drop is caught within a
  // day instead of within a week, for 6 extra searches per alert per week
  // instead of 48. Needs best_out/best_ret, which the Tuesday run records.
  if (!fullRun) {
    const bo = String(r.best_out || '').trim();
    const br = String(r.best_ret || '').trim();
    if (!bo || !br) continue;                       // nothing learned yet
    if (new Date(bo + 'T12:00:00Z') < today) continue;  // that weekend has passed
    out.push({ json: {
      alert_id: r.alert_id, chat_id: r.chat_id, language: r.language || 'en',
      origin: o, destination: d,
      origin_name: r.origin_name || o, dest_name: r.dest_name || d,
