           '&currency=EUR&hl=en&gl=de&type=1'
    }});
    continue;
  }
  for (let w = 0; w < weeks; w++) {
    const mon = add(anchor, w * 7);
    for (const pat of pats) {
      const off = OFFSETS[pat];
      const ob = iso(add(mon, off[0])), rt = iso(add(mon, off[1]));
      out.push({ json: {
        alert_id: r.alert_id, chat_id: r.chat_id, language: r.language || 'en',
        origin: o, destination: d,
