        level: pi.price_level || '',
        history: Array.isArray(pi.price_history) ? pi.price_history : null,
        airline: first.airline || '', stops: Math.max(0, legs.length - 1),
        duration: f.total_duration || null,
        link: gf(q.origin_name || q.origin, q.dest_name || q.destination, q.out, q.ret)
      };
    }
