  if (a.light && a.cheapest) {
    const prev = Number(a.last_notified) || 0;
    const drop = prev > 0 ? prev - a.cheapest.price : 0;
    a.dropped = prev > 0 && (drop >= 20 || drop / prev >= 0.10);
  }
  return a;
}).filter(a => a.cheapest && (!a.light || a.dropped));

