  if (a.trend && Math.abs(a.trend.deltaPct) >= 15) {
    const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    const from = eur(a.trend.base) + (a.trend.sinceMonth !== null ? ' in ' + MONTHS[a.trend.sinceMonth] : '');
