  L.push('<b>' + esc(de ? 'Wochenenden' : 'Weekends') + '</b>');
  for (const o of keep) {
    const mark = (o === c) ? ' ←' : '';
    L.push(esc(eur(o.price).padEnd(6) + ' ' + span(o)) + mark);
  }
  if (hidden.length) {
    const lo = hidden[0].price, hi = hidden[hidden.length - 1].price;
    L.push('<i>' + esc((de ? '+ ' : '+ ') + hidden.length +
      (de ? ' weitere von ' : ' more from ') + eur(lo) + ' to ' + eur(hi) +
