  }

  L.push('');
  if (a.budget > 0) {
    L.push(esc((de ? 'Budget ' : 'Budget ') + eur(a.budget) + ': ' + a.under.length + ' ' +
      (de ? 'von ' : 'of ') + a.weekends + (de ? ' Wochenenden darunter' : ' weekends under it')));
  }
  if (a.typical) L.push('<i>' + esc((de ? 'Ueblich fuer dieses Wochenende ' : 'Typical for that weekend ')
