  out.push({ json: {
    chat_id: a.chat_id, alert_id: a.alert_id, language: a.language,
    best_price: c.price, best_out: c.out, best_ret: c.ret,
    route: (a.origin_name || a.origin) + ' to ' + (a.dest_name || a.destination),
    dates_checked: a.weekends, searches: d.searches,
